mapper.select:
SELECT COUNT(*)
FROM members
WHERE company_id = #{companyId}
AND created >= #{start}
AND created <= #{end}

SELECT COUNT(*)
FROM aftersales a

LEFT JOIN orders_normal_orders o ON a.order_id = o.order_id

WHERE a.company_id = #{companyId}
AND a.create_time >= #{start}
AND a.create_time <= #{end}

AND o.order_class = #{orderClass}
AND o.act_id = #{actId}

SELECT IFNULL(SUM(r.refunded_fee), 0)
FROM aftersales_refund r

LEFT JOIN orders_normal_orders o ON r.order_id = o.order_id

WHERE r.company_id = #{companyId}
AND r.update_time >= #{start}
AND r.update_time <= #{end}
AND r.refund_status = 'SUCCESS'

AND o.order_class = #{orderClass}
AND o.act_id = #{actId}

SELECT IFNULL(SUM(CAST(t.total_fee AS SIGNED)), 0)
FROM trade t

LEFT JOIN orders_normal_orders o ON t.order_id = o.order_id

WHERE t.company_id = #{companyId}
AND t.trade_state IN ('REFUND_PROCESS', 'REFUND_SUCCESS', 'SUCCESS')
AND t.time_expire >= #{start}
AND t.time_expire <= #{end}

AND o.order_class = #{orderClass}
AND o.act_id = #{actId}

SELECT COUNT(*)
FROM orders_normal_orders
WHERE company_id = #{companyId}
AND create_time >= #{start}
AND create_time <= #{end}

AND order_class = #{orderClass}
AND act_id = #{actId}

SELECT COUNT(*)
FROM trade t

LEFT JOIN orders_normal_orders o ON t.order_id = o.order_id

WHERE t.company_id = #{companyId}
AND t.trade_state IN ('REFUND_PROCESS', 'REFUND_SUCCESS', 'SUCCESS')
AND t.time_expire >= #{start}
AND t.time_expire <= #{end}

AND o.order_class = #{orderClass}
AND o.act_id = #{actId}

SELECT IFNULL(SUM(CAST(total_fee AS SIGNED)), 0)
FROM orders_normal_orders
WHERE company_id = #{companyId}
AND create_time >= #{start}
AND create_time <= #{end}

AND order_class = #{orderClass}
AND act_id = #{actId}
